<script setup lang="ts">
import { v4 as newRequestKey } from "uuid";
import Modal from "@papilio/ui/Modal.vue";
import { computed, onUnmounted, ref, watch } from "vue";
import { useAuth } from "@papilio/auth";
import { item, query, request, type Page, type NotificationRecord, type NotificationAvailability, type NotificationAttempt, type NotificationRecovery } from "@papilio/api";
import { faDate, faNumber, toman } from "@papilio/ui";
import { useI18n } from "vue-i18n";
import { kinds, outcomes, statuses } from "./labels";
const props=defineProps<{audience:"admin"|"customer";customerId?:number}>();
const auth=useAuth(),{t}=useI18n();const prefix=computed(()=>`/v1/${props.audience}/notifications`);
const observedKinds=ref<NotificationRecord["kind"][]>([]);
const rows=ref<NotificationRecord[]>([]);const selected=ref<NotificationRecord|null>(null);const policy=ref<NotificationAvailability|null>(null);
const q=ref("");const kind=ref("");const status=ref("");const read=ref("");const page=ref(1);const pages=ref(1);const total=ref(0);
const loading=ref(false);const selecting=ref(false);const busy=ref(false);const error=ref("");const notice=ref("");const auditError=ref("");const auditLoading=ref(false);
const attempts=ref<NotificationAttempt[]>([]);const history=ref<NotificationRecovery[]>([]);const attemptPage=ref(1);const attemptPages=ref(1);const historyPage=ref(1);const historyPages=ref(1);
const title=ref("");const body=ref("");const draftCustomer=ref<number|undefined>();const key=ref(newRequestKey());const reason=ref("");const action=ref<"retry"|"cancel">("retry");
let listVersion=0;let selectionVersion=0;let auditVersion=0;
const knownCustomer=computed(()=>props.customerId??selected.value?.customer_id);
const mayCreate=computed(()=>props.audience==="admin"&&auth.can("notifications","create")&&policy.value?.capacity_valid&&policy.value.enabled&&policy.value.templates.manual.enabled);
const mayRecover=computed(()=>props.audience==="admin"&&auth.can("notifications","update")&&selected.value?.revision!==undefined&&["pending","retry","ambiguous","failed"].includes(selected.value?.status??""));
const visibleKinds=computed(()=>Object.fromEntries(Object.entries(kinds).filter(([value])=>!value.startsWith("checkout_")||policy.value?.supported_kinds?.includes(value as NotificationRecord["kind"])||observedKinds.value.includes(value as NotificationRecord["kind"])).map(([value])=>[value,t(`notificationKinds.${value}`)])));
const visibleStatuses=computed(()=>Object.fromEntries(Object.keys(statuses).map(value=>[value,t(`notificationStatuses.${value}`)])));
const visibleOutcomes=computed(()=>Object.fromEntries(Object.keys(outcomes).map(value=>[value,t(`notificationOutcomes.${value}`)])));
const messageSize=computed(()=>Array.from(title.value+"\n"+body.value).length);
const validDraft=computed(()=>title.value.trim()&&body.value.trim()&&Array.from(title.value).length<=160&&policy.value&&messageSize.value<=policy.value.max_message_chars);
function fail(cause:unknown):string{return cause instanceof Error?cause.message:t("notificationRecords.operationFailed");}
async function load():Promise<void>{const stamp=++listVersion;loading.value=true;error.value="";try{const result=await request<Page<NotificationRecord>>(`${prefix.value}?${query({q:q.value,kind:kind.value||undefined,is_read:read.value?read.value==="read":undefined,status:props.audience==="admin"?status.value||undefined:undefined,customer_id:props.audience==="admin"?props.customerId:undefined,page:page.value})}`);const settings=props.audience==="admin"?await item<NotificationAvailability>(`${prefix.value}/policy`):null;if(stamp!==listVersion)return;observedKinds.value=[...new Set([...observedKinds.value,...result.data.map(row=>row.kind)])];rows.value=result.data;pages.value=result.meta.pager?.total_pages??1;total.value=result.meta.pager?.total_items??0;policy.value=settings;}catch(cause){if(stamp===listVersion)error.value=fail(cause);}finally{if(stamp===listVersion)loading.value=false;}}
async function audit():Promise<void>{const row=selected.value;if(!row||props.audience!=="admin")return;const stamp=++auditVersion;auditLoading.value=true;auditError.value="";try{const [a,h]=await Promise.all([request<Page<NotificationAttempt>>(`${prefix.value}/${row.id}/attempts?${query({page:attemptPage.value})}`),request<Page<NotificationRecovery>>(`${prefix.value}/${row.id}/history?${query({page:historyPage.value})}`)]);if(stamp!==auditVersion||selected.value?.id!==row.id)return;attempts.value=a.data;attemptPages.value=a.meta.pager?.total_pages??1;history.value=h.data;historyPages.value=h.meta.pager?.total_pages??1;}catch(cause){if(stamp===auditVersion)auditError.value=fail(cause);}finally{if(stamp===auditVersion)auditLoading.value=false;}}
async function select(row:NotificationRecord,preserve=false):Promise<void>{if(busy.value||selecting.value)return;const stamp=++selectionVersion;selecting.value=true;error.value="";try{const fresh=await item<NotificationRecord>(`${prefix.value}/${row.id}`);if(stamp!==selectionVersion)return;selected.value=fresh;if(!preserve){reason.value="";action.value="retry";attemptPage.value=1;historyPage.value=1;attempts.value=[];history.value=[];}if(props.audience==="admin")void audit();if(preserve)notice.value=t("notificationRecords.retained");}catch(cause){if(stamp===selectionVersion)error.value=fail(cause);}finally{if(stamp===selectionVersion)selecting.value=false;}}
const createOpen=ref(false);
function startDraft():void{if(busy.value||!mayCreate.value||knownCustomer.value===undefined)return;if(draftCustomer.value===undefined){draftCustomer.value=knownCustomer.value;title.value=policy.value!.templates.manual.title;body.value=policy.value!.templates.manual.body;key.value=newRequestKey();}createOpen.value=true;}
async function create():Promise<void>{if(busy.value||!mayCreate.value||draftCustomer.value===undefined||!validDraft.value)return;const stamp=selectionVersion;busy.value=true;error.value="";notice.value="";try{const result=await item<NotificationRecord>(prefix.value,"POST",{customer_id:draftCustomer.value,request_key:key.value,title:title.value,body:body.value});if(stamp!==selectionVersion)return;selected.value=result;title.value="";body.value="";draftCustomer.value=undefined;key.value=newRequestKey();createOpen.value=false;notice.value=t("notificationRecords.created");await load();void audit();}catch(cause){if(stamp===selectionVersion)error.value=fail(cause);}finally{busy.value=false;}}
async function setRead():Promise<void>{const row=selected.value;if(props.audience!=="customer"||!row||busy.value)return;const stamp=selectionVersion;busy.value=true;error.value="";try{const result=await item<NotificationRecord>(`${prefix.value}/${row.id}/read`,"PUT",{is_read:!row.is_read});if(stamp!==selectionVersion)return;selected.value=result;await load();}catch(cause){if(stamp===selectionVersion)error.value=fail(cause);}finally{busy.value=false;}}
async function recover():Promise<void>{const row=selected.value;if(!row||!mayRecover.value||busy.value)return;const stamp=selectionVersion;busy.value=true;error.value="";notice.value="";try{const result=await item<NotificationRecord>(`${prefix.value}/${row.id}/recovery`,"PUT",{expected_revision:row.revision,action:action.value,reason:reason.value});if(stamp!==selectionVersion)return;selected.value=result;reason.value="";notice.value=t("notificationRecords.recovered");await load();void audit();}catch(cause){if(stamp===selectionVersion)error.value=fail(cause);}finally{busy.value=false;}}
async function dispatch():Promise<void>{const row=selected.value;if(!row||busy.value||!auth.can("notifications","update"))return;const stamp=selectionVersion;busy.value=true;error.value="";notice.value="";try{await item(`${prefix.value}/${row.id}/dispatch`,"POST");if(stamp===selectionVersion)notice.value=t("notificationRecords.dispatchQueued");}catch(cause){if(stamp===selectionVersion)error.value=fail(cause);}finally{busy.value=false;}}
const sourceLink=computed(()=>{const row=selected.value;if(!row||row.record_id===null)return null;if(["checkout_action_required","checkout_cancelled","checkout_expired"].includes(row.kind)&&props.audience==="customer")return {path:"/account",query:{checkout_id:row.record_id}};if(row.kind==="support_reply"&&(props.audience==="customer"||auth.can("support")))return {path:props.audience==="customer"?"/account/support":"/support",query:{ticket_id:row.record_id,...(props.audience==="admin"?{customer_id:row.customer_id}:{})}};if(row.kind==="payment_approved"&&(props.audience==="customer"||auth.can("payments")))return {path:props.audience==="customer"?"/account":"/payments",query:{topup_id:row.record_id}};if(["expiry_soon","renewal_unfunded","provisioning_failed","subscription_active","tier_changed","discount_applied","volume_low","renewal_available"].includes(row.kind)&&(props.audience==="customer"||auth.can("subscriptions")))return {path:props.audience==="customer"?"/account":"/subscriptions",query:{subscription_id:row.record_id}};return null;});
watch([q,kind,status,read],()=>{page.value=1;void load();});
watch(()=>[props.audience,props.customerId],()=>{selectionVersion++;auditVersion++;observedKinds.value=[];selected.value=null;createOpen.value=false;draftCustomer.value=undefined;title.value="";body.value="";key.value=newRequestKey();page.value=1;void load();},{immediate:true});
onUnmounted(()=>{listVersion++;selectionVersion++;auditVersion++;});
</script>
<template><div class="stack"><p v-if="error" class="message error" role="alert">{{error}}</p><p v-if="notice" class="message success" role="status">{{notice}}</p><p v-if="policy&&!policy.capacity_valid" class="hint-box">{{t("notificationRecords.capacityWarning")}}</p><p v-if="policy&&!policy.outbound_available" class="hint-box">{{t("notificationRecords.externalDisabled")}}</p><div :class="{split:!!selected}"><section class="card card-pad"><h2>{{t("notificationRecords.title")}}</h2><div class="form-grid"><label class="field"><span>{{t("notificationRecords.search")}}</span><input v-model="q" :disabled="busy" /></label><label class="field"><span>{{t("notificationRecords.kind")}}</span><select v-model="kind" :aria-label="t('notificationRecords.kind')" :disabled="busy"><option value="">{{t("notificationRecords.all")}}</option><option v-for="(label,value) in visibleKinds" :key="value" :value="value">{{label}}</option></select></label><label class="field"><span>{{t("notificationRecords.readStatus")}}</span><select v-model="read" :aria-label="t('notificationRecords.readStatus')" :disabled="busy"><option value="">{{t("notificationRecords.all")}}</option><option value="unread">{{t("notificationRecords.unread")}}</option><option value="read">{{t("notificationRecords.read")}}</option></select></label><label v-if="audience==='admin'" class="field"><span>{{t("notificationRecords.deliveryStatus")}}</span><select v-model="status" :aria-label="t('notificationRecords.deliveryStatus')" :disabled="busy"><option value="">{{t("notificationRecords.all")}}</option><option v-for="(label,value) in visibleStatuses" :key="value" :value="value">{{label}}</option></select></label><button class="btn secondary" :disabled="loading||busy" @click="load">{{t("notificationRecords.refresh")}}</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>{{t("notificationRecords.name")}}</th><th v-if="audience==='admin'">{{t("notificationRecords.customer")}}</th><th>{{t("notificationRecords.status")}}</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id" tabindex="0" :class="{'selected-row':selected?.id===row.id}" @click="select(row)" @keydown.enter="select(row)"><td>{{row.title}} · {{faNumber(row.id)}}</td><td v-if="audience==='admin'&&row.customer_id!==undefined">{{faNumber(row.customer_id)}}</td><td>{{audience==='admin'&&row.status?statuses[row.status]:row.is_read?t('notificationRecords.read'):t('notificationRecords.unread')}}</td></tr></tbody></table></div><p v-if="loading">{{t("notificationRecords.loading")}}</p><p v-else-if="!rows.length&&!error">{{t("notificationRecords.empty")}}</p><div class="pager"><button :disabled="page<=1||loading||busy" @click="page--;load()">‹</button><span>{{faNumber(page)}} · {{faNumber(total)}} {{t("notificationRecords.count")}}</span><button :disabled="page>=pages||loading||busy" @click="page++;load()">›</button></div></section>
<section v-if="selected" class="card card-pad stack"><h2>{{selected.title}}</h2><p>{{faDate(selected.created_at)}} · {{visibleKinds[selected.kind]??t(`notificationKinds.${selected.kind}`)}}</p><p class="notification-body">{{selected.body}}</p><section v-if="selected.subscription_context" class="hint-box" :aria-label="t('notificationRecords.capturedAlert')"><h3>{{t("notificationRecords.atCreation")}}</h3><p>{{faDate(selected.subscription_context.captured_at)}} · {{t("notificationRecords.generation")}} {{selected.subscription_context.generation}} · {{t("notificationRecords.rule")}} {{selected.subscription_context.threshold_code}}</p><p>{{t("notificationRecords.used")}}: {{faNumber(selected.subscription_context.used_bytes/1024**3)}} GiB · {{t("notificationRecords.remaining")}}: {{selected.subscription_context.remaining_bytes===null?t("notificationRecords.unlimited"):faNumber(selected.subscription_context.remaining_bytes/1024**3)+" GiB"}}</p><p>{{t("notificationRecords.expiry")}}: {{selected.subscription_context.expires_at?faDate(selected.subscription_context.expires_at):t("notificationRecords.noExpiry")}} · {{t("notificationRecords.renewalPrice")}}: {{selected.subscription_context.renewal_price_rial===null?t("notificationRecords.unavailable"):toman(selected.subscription_context.renewal_price_rial)}}</p><p>{{t("notificationRecords.openService")}}</p></section><RouterLink v-if="sourceLink" class="btn secondary" :to="sourceLink">{{t("notificationRecords.relatedRecord")}}</RouterLink><button v-if="audience==='customer'" class="btn secondary" :disabled="busy||selecting" @click="setRead">{{selected.is_read?t('notificationRecords.markUnread'):t('notificationRecords.markRead')}}</button><template v-else><p v-if="selected.created_by_staff_id!=null">{{t("notificationRecords.createdByStaff")}}: {{faNumber(selected.created_by_staff_id)}}</p><p v-else>{{t("notificationRecords.automatic")}}</p><p v-if="selected.status">{{visibleStatuses[selected.status]}} · {{t("notificationRecords.attemptCount",{count:faNumber(selected.attempts!)})}}</p><p v-if="selected.next_attempt_at">{{t("notificationRecords.nextAttempt")}}: {{faDate(selected.next_attempt_at)}}</p><p v-if="selected.error_code" class="hint-box">{{t("notificationRecords.errorHint")}}</p><button class="btn secondary" :disabled="busy||selecting" @click="select(selected,true)">{{t("notificationRecords.refreshRetain")}}</button><button v-if="auth.can('notifications','update')" class="btn secondary" :disabled="busy||selecting" @click="dispatch">{{t("notificationRecords.checkDelivery")}}</button><form v-if="mayRecover" class="form-grid" @submit.prevent="recover"><label class="field"><span>{{t("notificationRecords.recoveryDecision")}}</span><select v-model="action" :aria-label="t('notificationRecords.recoveryDecision')" :disabled="busy"><option value="retry">{{t("notificationRecords.retryDuplicate")}}</option><option value="cancel">{{t("notificationRecords.cancelDelivery")}}</option></select></label><label class="field"><span>{{t("notificationRecords.recoveryReason")}}</span><input v-model="reason" required minlength="3" maxlength="250" :disabled="busy" /></label><button class="btn" :disabled="busy||selecting||reason.trim().length<3">{{t("notificationRecords.recordRecovery")}}</button></form><p v-if="auditError" class="message error" role="alert">{{auditError}}</p><p v-if="auditLoading">{{t("notificationRecords.loadingHistory")}}</p><h3>{{t("notificationRecords.deliveryAttempts")}}</h3><article v-for="row in attempts" :key="row.id"><p>{{faNumber(row.attempt)}} · {{visibleOutcomes[row.outcome]??t("notificationRecords.needsReview")}} · {{faDate(row.created_at)}}</p></article><div class="pager"><button :disabled="attemptPage<=1||auditLoading" @click="attemptPage--;audit()">‹</button><span>{{faNumber(attemptPage)}}</span><button :disabled="attemptPage>=attemptPages||auditLoading" @click="attemptPage++;audit()">›</button></div><h3>{{t("notificationRecords.staffDecisions")}}</h3><article v-for="row in history" :key="row.id"><p>{{row.action==='retry'?t('notificationRecords.retry'):t('notificationRecords.cancel')}} · {{row.reason}} · {{faDate(row.created_at)}}</p></article><div class="pager"><button :disabled="historyPage<=1||auditLoading" @click="historyPage--;audit()">‹</button><span>{{faNumber(historyPage)}}</span><button :disabled="historyPage>=historyPages||auditLoading" @click="historyPage++;audit()">›</button></div></template></section></div>
<button v-if="mayCreate&&knownCustomer!==undefined" class="btn secondary" :disabled="busy" @click="startDraft">{{draftCustomer===undefined?t('notificationRecords.createForCustomer',{id:faNumber(knownCustomer)}):t('notificationRecords.continueDraft',{id:faNumber(draftCustomer)})}}</button><Modal v-if="mayCreate&&draftCustomer!==undefined" v-model="createOpen" :title="t('notificationRecords.createTitle')" :busy="busy" wide><p>{{t("notificationRecords.forCustomer",{id:faNumber(draftCustomer)})}}</p><p v-if="error" class="message error" role="alert">{{error}}</p><form class="form-grid" @submit.prevent="create"><label class="field"><span>{{t("notificationRecords.messageTitle")}}</span><input v-model="title" required :disabled="busy" /></label><label class="field"><span>{{t("notificationRecords.messageBody")}}</span><textarea v-model="body" :aria-label="t('notificationRecords.messageBody')" required :disabled="busy" /><small>{{faNumber(messageSize)}} / {{faNumber(policy!.max_message_chars)}}</small></label><button class="btn" :disabled="busy||selecting||!validDraft">{{t("notificationRecords.create")}}</button></form></Modal><p v-if="mayCreate&&knownCustomer===undefined" class="hint-box">{{t("notificationRecords.recipientRequired")}}</p></div></template>
<style scoped>.notification-body{white-space:pre-wrap;overflow-wrap:anywhere}.stack{min-width:0}textarea{min-height:130px}</style>
